/* Review prototype. Wallets are read for address and network only; no approvals, signatures or fund transactions. */
var D;
var params = new URLSearchParams(location.search);
var S = {
  lang:I18N.initial,
  themeMode:ForeaTheme.getMode(),theme:ForeaTheme.resolve(ForeaTheme.getMode()),
  route:'home',agentTab:0,liquidityTab:0,monitorTab:'positions',
  connected:false,walletAddress:'',walletChainId:null,accountSub:'',tokenCycleUsed:0,account:0,walletBalance:3250.00,capital:1000,amount:1000,
  agentState:params.get('scene')||'inactive',elapsed:14643,startedAt:Date.now(),
  category:'all',topic:'',tradeFilter:'all',tapePaused:false,tapeOldest:false,search:'',marketPage:0,bookMarket:'',
  swapAmount:25,swapReverse:false,slippage:.5,showSlippage:false,
  services:[],records:[],accountCache:{},overlay:null,selectedMarket:null
};
if(S.agentState==='inactive'){S.capital=0;S.elapsed=0}
if(S.agentState==='cancelling'){S.elapsed=9043;S.exitSec=15600}
if(S.agentState==='resuming')S.elapsed=183;
if(S.agentState==='stopped')S.elapsed=0;
S.custody=null;S.custodyFee=0;S.runMode='cycle';
if(S.agentState==='custody'){S.agentState='running';S.custody={startedAt:Date.now()-26*3600000};S.custodyFee=30;S.capital=970}
if(S.agentState==='inactive')S.amount='';
// Leo PRD 11-10 §5.1: 标准 and 托管 are two products an account can hold at the same time, sharing one card.
// The fields in SLOT belong to the product on screen; the other product's values are parked in S.slots.
var SLOT=['agentState','capital','amount','elapsed','startedAt','exitSec','cycleSeed','realized','custody','custodyFee','tokenCycleUsed','shownLock'];
var emptySlot=()=>({agentState:'inactive',capital:0,amount:'',elapsed:0,startedAt:Date.now(),exitSec:0,cycleSeed:'',realized:0,custody:null,custodyFee:0,tokenCycleUsed:0,shownLock:undefined});
S.product=S.custody?'custody':'standard';S.runMode=S.custody?'custody':'cycle';S.slots={standard:emptySlot(),custody:emptySlot()};
function saveSlot(){const o={};for(const k of SLOT)o[k]=S[k];S.slots[S.product]=o}
function loadSlot(name){saveSlot();S.product=name;Object.assign(S,S.slots[name]);S.runMode=name==='custody'?'custody':'cycle'}
function otherProduct(){return S.product==='custody'?'standard':'custody'}
function withOther(fn){const cur=S.product;loadSlot(otherProduct());try{return fn()}finally{loadSlot(cur)}}
var U = {
  brand:'Maat',
  // Leo 11-03 doc: custody mode is optional, up to 30 days, fee = 3% of principal, can stop after 24H;
  // 50% of the fee is the direct referral reward (MAAT from the reward pool), 50% buys back and burns MAAT.
  // Demo choices (Leo did not specify): the fee is taken from the Agent account when custody starts and is not refunded on an early stop.
  custody:{rate:0.03,days:30,minHours:24,buyback:0.5,referral:0.5},
  // Leo PRD 11-10 §5.1: 平仓 lasts a random 3–5H (drawn per cycle); 继续运行 unlocks after 3H of it; 恢复中 lasts 10 minutes.
  limits:()=>S.product==='custody'?[100,5000]:[20,1000],
  limitText:()=>S.product==='custody'?'100–5,000':'20–1,000',
  resumeSec:600,exitMinSec:10800,exitMaxSec:18000,continueAfterSec:10800,
  t:(zh,en,x)=>I18N.t(S.lang,zh,en,x),
  zh:()=>I18N.zh(S.lang),
  esc:s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),
  money:(n,compact=false,digits=2)=>Number(n).toLocaleString('en-US',compact?{notation:'compact',maximumFractionDigits:2}:{minimumFractionDigits:digits,maximumFractionDigits:digits}),
  badge:(label,tone='')=>`<span class="badge ${tone}"><span class="dot"></span>${label}</span>`,
  accountBalance:i=>i===S.account?S.walletBalance:(S.accountCache[i]?.walletBalance??(i===0?3250:850)),
  record:(label,amount,unit='USDC')=>S.records.unshift({label,amount,unit,time:Date.now()}),
  address:()=>S.walletAddress?S.walletAddress.slice(0,6)+'…'+S.walletAddress.slice(-4):U.t('访客','Guest'),
  avatar:()=>Account.avatar(),
  wave:()=>`<svg class="wave-field" viewBox="0 0 600 450" fill="none" aria-hidden="true">${Array.from({length:26},(_,i)=>`<path d="M-30 ${60+i*13} C100 ${220+i*8}, 180 ${-40+i*11}, 300 ${110+i*10} S470 ${390-i*6}, 660 ${120+i*8}" stroke="currentColor" stroke-width=".7" opacity="${.22+i*.018}"></path>`).join('')}</svg>`,
  stamp:(ms,seconds=false)=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Kuala_Lumpur'}).formatToParts(new Date(ms)).map(x=>[x.type,x.value]));return `${p.month}-${p.day} ${p.hour}:${p.minute}${seconds?':'+p.second:''}`},
  captureTime:()=>U.stamp(Date.parse(D.fetchedAt))+' UTC+8',
  // Recent Activity (Leo 11-05 #27, echo 11-06): high-liquidity open Polymarket events shown as liquidity-service activity,
  // newest first, on a slowly scrolling vertical timeline. Times step back from now; the list is doubled for a seamless loop.
  activityItems:()=>{const pool=U.featured().filter(m=>U.eligible(m)&&m.acceptingOrders!==false&&Date.parse(m.endDate)>Date.now()),now=Math.floor(Date.now()/60000)*60000;let ago=4;return pool.map((m,i)=>{const at=now-ago*60000;ago+=7+Math.round(Engine.rnd('activity:'+m.id,Math.floor(Date.now()/3600000))*16);return {m,at,k:i%3}})},
  activityRow:({m,at,k})=>`<div class="timeline-item"><time>${U.stamp(at)} UTC+8</time><p>${U.esc(m.question)}</p><span class="badge ${['','gray','purple'][k]}">${icon(['drop','check','coins'][k],'',11)}${U.t(['流动性服务已开始','流动性服务已结束','流动性服务已结算'][k],['Liquidity service started','Liquidity service ended','Liquidity service settled'][k])}</span></div>`,
  activityFeed:()=>{const rows=U.activityItems().map(U.activityRow).join('');return `<div class="activity-feed"><div class="timeline activity-scroll">${rows}<div class="activity-loop" aria-hidden="true">${rows}</div></div></div>`},
  // Leo 11-05 #26: Polymarket prices read in dollars ($0.24), not cents.
  backBtn:(fallback='home')=>`<button class="icon-btn page-back" data-action="back" data-value="${fallback}" aria-label="${U.t('返回','Back')}">${icon('chevron','back-icon',21)}</button>`,
  // Prices keep their real precision (0.175 → $0.175, 0.24 → $0.24) so they match the implied probability next to them.
  usd:p=>'$'+(Math.round(Number(p)*1000)/1000).toFixed(3).replace(/0$/,''),
  source:(kind,time)=>`<div class="source"><a href="#sources">${icon('globe','',11)}${U.t('数据来源','Data source')} · Polymarket${icon('chevron','',10)}</a><span>${U.t('更新于','Updated')} ${time?U.stamp(time)+' UTC+8':U.captureTime()}</span></div>`,
  tabs:(zh,en,current,action)=>`<div class="tabs" role="tablist">${zh.map((x,i)=>`<button role="tab" aria-selected="${i===current}" class="${i===current?'active':''}" data-action="${action}" data-value="${i}">${U.t(x,en[i])}</button>`).join('')}</div>`,
  pending:(title,desc,ic='layers',cta='',action='')=>`<div class="panel"><div class="empty"><div class="empty-icon">${icon(ic,'',29)}</div><h2>${title}</h2><p>${desc}</p>${cta?`<button class="btn primary" data-action="${action}">${cta}${icon('arrow','',15)}</button>`:`<span class="badge gray">${U.t('暂未开放','Not available yet')}</span>`}</div></div>`,
  metric:(label,value,unit,ic,foot)=>`<article class="metric-card"><div class="between"><span class="label">${label}</span><span class="metric-icon">${icon(ic)}</span></div><div class="num">${value}<small>${unit}</small></div>${foot?`<p class="foot">${foot}</p>`:''}</article>`,
  category:m=>{const tags=m.tagLabels.join(' ').toLowerCase();return /crypto|bitcoin/.test(tags)?'crypto':/sport|soccer|esports/.test(tags)?'sports':/economy|fed rates|\bfed\b/.test(tags)?'economy':/geopolitics|france|iran|russia/.test(tags)?'world':'politics'},
  topicNames:{'Iran':['伊朗','Iran'],'Bitcoin':['比特币','Bitcoin'],'Fed':['美联储','Fed'],'EPL':['英超','Premier League'],'Esports':['电竞','Esports'],'France':['法国大选','French election'],'Russia':['俄罗斯','Russia'],'Ukraine':['乌克兰','Ukraine'],'Middle East':['中东','Middle East'],'Elections':['选举','Elections'],'Midterms':['中期选举','Midterms'],'Senate':['参议院','Senate'],'Trump':['特朗普','Trump'],'Science':['科学','Science']},
  topics:()=>{const n={};for(const m of D.markets)for(const tag of new Set(m.tagLabels))if(U.topicNames[tag])n[tag]=(n[tag]||0)+1;return Object.keys(n).sort((a,b)=>n[b]-n[a]).slice(0,5).map(tag=>[tag,U.t(...U.topicNames[tag])])},
  categoryLabel:c=>({all:U.t('全部','All'),politics:U.t('政治','Politics'),crypto:U.t('加密货币','Crypto'),sports:U.t('体育','Sports'),world:U.t('世界','World'),economy:U.t('经济','Economy')})[c]||c,
  eligible:m=>m.liquidity>=100000,
  // Leo PRD 11-10 §5.1: each 8H cycle ends 0.2–0.4% up after MAAT usage. The cycle P&L (before MAAT) moves in steps with
  // drawdowns through the run and exit phases, first moving 2 minutes after the start, and is fixed once stopped.
  // Continuing rolls principal + P&L into the next cycle; custody cycles renew without compounding (realized).
  cyclePos:()=>{const e=Math.max(0,S.elapsed+Math.floor((Date.now()-S.startedAt)/1000)),X=S.exitSec||14400;return S.agentState==='running'?Math.min(e,28800):S.agentState==='cancelling'?28800+Math.min(e,X):S.agentState==='stopped'?28800+X:0},
  cycleTarget:()=>{const rate=.002+Engine.hash((S.cycleSeed||'base')+':rate')*.002;return Number((S.capital*rate+Tokenomics.tokenValue(S.tokenCycleUsed)).toFixed(2))},
  cycleGross:()=>{
    if(!(S.capital>0)||!['running','cancelling','stopped'].includes(S.agentState))return 0;
    const pos=U.cyclePos(),G=U.cycleTarget(),T=28800,X=S.exitSec||14400,seed=S.cycleSeed||'base',r=k=>Engine.hash(seed+':'+k);
    if(S.agentState==='stopped'||pos>=T+X)return G;
    let at=120,i=0,v=0;
    while(at<=pos){const f=Math.min(1,at/T),amp=at<=T?.45*G*Math.sqrt(f)*(1-.6*f):.25*G*(1-(at-T)/X);v=G*Math.pow(f,.85)+amp*(r(i)*2-1);i++;at+=at<T?60+Math.round(r('gap'+i)*540):300+Math.round(r('gap'+i)*600)}
    return Number(v.toFixed(2));
  },
  performance:()=>{const on=S.capital>0,gross=on?U.cycleGross():0,realized=on?Number(S.realized||0):0,tokenCost=on?Tokenomics.tokenValue(S.tokenCycleUsed):0,custodyFee=on?Number((S.custodyFee||0).toFixed(8)):0,net=Number((gross-tokenCost).toFixed(8));return {gross,realized,tokenCost,custodyFee,buyback:Number((custodyFee*U.custody.buyback).toFixed(8)),net,equity:Number((S.capital+realized+net).toFixed(8)),cashBalance:Number((S.capital+realized+gross).toFixed(8)),grossPct:on?gross/S.capital*100:0,netPct:on?(realized+net)/S.capital*100:0}},
  pct:n=>(n>=0?'+':'')+n.toFixed(3)+'%',
  filteredMarkets:()=>{const raw=S.search.trim().toLowerCase();const alias={'比特币':'bitcoin','参议院':'senate','英超':'epl','中期选举':'midterms','中期':'midterms','法国选举':'french','法国大选':'french','法国':'france','伊朗':'iran','俄罗斯':'russia','美联储':'fed','利率':'fed rates','电竞':'esports','中东':'middle east','特朗普':'trump','政治':'politics','体育':'sports','加密货币':'crypto','经济':'economy','民主党':'democratic','共和党':'republican'};const q=alias[raw]||raw;const list=q?D.markets.filter(m=>(m.question+' '+m.tagLabels.join(' ')+' '+U.categoryLabel(U.category(m))).toLowerCase().includes(q)):U.featured().filter(U.eligible).slice(0,9);return list.filter(m=>S.category==='all'||U.category(m)===S.category)},
  featured:()=>[0,7,6,1,9,3,5,8,2,4,10,11].map(i=>D.markets[i]).filter(Boolean),
  thumb:m=>m.localImage?`<img class="market-thumb" src="${U.esc(m.localImage)}" alt="" loading="lazy">`:`<span class="market-thumb">${icon(U.category(m)==='crypto'?'coins':U.category(m)==='sports'?'shield':'globe','',20)}</span>`,
  marketCard:(m,compact=false)=>{
    const book=D.orderBooks.find(b=>b.marketId===m.id);
    const sp=Engine.spread(m),spread=sp==null?'—':U.usd(sp,true);const open=m.acceptingOrders!==false&&Date.parse(m.endDate)>Date.now();
    return `<article class="panel market-card"><div class="between market-card-topline"><span class="market-category">${U.categoryLabel(U.category(m))}</span></div><div class="top">${U.thumb(m)}<h3 class="title" title="${U.esc(m.question)}">${U.esc(m.question)}</h3></div><div class="market-quotes"><div><span class="positive">YES ${U.t('参考价','price')}</span><strong>${U.usd(m.prices[0])}</strong><small>${(m.prices[0]*100).toFixed(1)}% ${U.t('隐含概率','implied')}</small></div><div><span class="negative">NO ${U.t('参考价','price')}</span><strong>${U.usd(m.prices[1])}</strong><small>${(m.prices[1]*100).toFixed(1)}% ${U.t('隐含概率','implied')}</small></div></div><div class="market-detail-grid"><div><span>${U.t('24H 成交额','24H volume')}</span><b>$${U.money(m.volume24hr,true)}</b></div><div><span>${U.t('盘口流动性','Market liquidity')}</span><b>$${U.money(m.liquidity,true)}</b></div><div><span>YES ${U.t('买卖价差','spread')}</span><b>${spread}</b></div><div><span>${U.t('盘口状态','Market status')}</span><b class="${open?'positive':'muted'}">${open?U.t('开放交易','Trading open'):U.t('已截止','Closed')}</b></div></div>${compact?`<a class="text-link" href="https://polymarket.com/event/${U.esc(m.eventSlug||m.slug)}" target="_blank" rel="noopener noreferrer">${U.t('查看预测事件','View market')}${icon('external','',12)}</a>`:U.eligible(m)&&open?`<button class="btn secondary block" data-action="apply" data-value="${m.id}">${U.t('申请流动性服务','Apply for liquidity service')}${icon('arrow','',13)}</button>`:`<div class="unsupported">${icon('lock','',12)} ${U.t('交易深度差，不支持申请服务','Order book too thin to apply')}</div>`}</article>`;
  },
  // Demo parameter pending Leo: a service settles 10 minutes after its 12H term ends; 4% fee is deducted at settlement.
  serviceSettleMs:10*60000,
  serviceInfo:s=>{const duration=12*3600000,elapsed=Math.max(0,Date.now()-(s.startedAt||Date.now())),remaining=Math.max(0,duration-elapsed);let status=s.withdrawn?'withdrawn':s.status;if(status==='active'&&remaining===0)status=elapsed>=duration+U.serviceSettleMs?'settled':'ended';const claimable=Number((s.claimableAmount??s.amount*.96).toFixed(8));return {status,claimable,fee:Number((s.amount-claimable).toFixed(8)),// 11-06 走查 #43 #44: Leo's order 已开始 → 已结束 → 已结算 (then 已提出); an ended service shows when it settles.
    label:({active:U.t('已开始','Started'),ended:U.t('已结束','Ended'),settled:U.t('已结算','Settled'),withdrawn:U.t('已提出','Withdrawn')})[status],tone:({active:'',ended:'amber',settled:'purple',withdrawn:'muted'})[status],progress:Math.min(100,elapsed/duration*100),time:status==='active'?`${String(Math.floor(remaining/3600000)).padStart(2,'0')}H ${String(Math.floor(remaining%3600000/60000)).padStart(2,'0')}M`:status==='ended'?U.t('预计 ','Settles ')+U.stamp((s.startedAt||Date.now())+duration+U.serviceSettleMs)+U.t(' 结算',''):'12H / 12H'}},
  model:m=>Engine.model(m),
  signalRow:(m,i)=>{const p=Engine.pct(Engine.model(m)),mk=Engine.pct(Number(m.prices[0])),score=Engine.score(m),yes=Engine.edge(m)>0;return `<div class="signal-row"><div class="signal-top">${U.thumb(m)}<div class="signal-head"><h3 class="signal-title" title="${U.esc(m.question)}">${U.esc(m.question)}</h3></div></div><div class="signal-probs"><span class="muted">${U.t('交易方向','Direction')}</span><div class="prob-header"><span class="${yes?'yes-label':'off-label'}">YES</span></div><div class="prob-header"><span class="${yes?'off-label':'no-label'}">NO</span></div><span class="muted">${U.t('隐含概率','Implied probability')}</span><span class="value">${mk.yes}%</span><span class="value">${mk.no}%</span><span class="muted">${U.t('模型估计概率','Model estimate')}</span><span class="value${yes?' accent':''}">${p.yes}%</span><span class="value${yes?'':' accent'}">${p.no}%</span></div><div class="between"><span class="score"><span class="muted">${U.t('模型信号评分','Signal score')}</span><span class="score-bar"><span style="width:${score}%"></span></span><b>${score}<span class="quiet"> / 100</span></b></span></div><time class="signal-time">${U.t('信号生成时间','Generated')} ${U.stamp(Engine.signalTime(i))} UTC+8</time></div>`},
  // Leo PRD 11-10: feeds scroll at a steady pace and pause on touch / hover (same mechanism as Liquidity Recent Activity).
  ticker:(rows,cls='',sec=48)=>`<div class="activity-feed ticker ${cls}" style="--ticker-dur:${sec}s"><div class="activity-scroll">${rows}<div class="activity-loop" aria-hidden="true">${rows}</div></div></div>`,
  // Market Monitor rows, one layout per subtab (Leo 11-02 mock images, re-sent 11-05).
  spark:(pts,up)=>{if(pts.length<2)return '';const w=84,h=26,min=Math.min(...pts),max=Math.max(...pts),y=p=>max===min?h/2:h-3-(p-min)/(max-min)*(h-6);return `<svg class="spark ${up?'positive':'negative'}" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><polyline points="${pts.map((p,i)=>(i/(pts.length-1)*w).toFixed(1)+','+y(p).toFixed(1)).join(' ')}" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round"/></svg>`},
  // 当前持仓: held side's real price (NO = 100 − YES, as elsewhere), its real 24H change and trend line; no position value (Leo: there is no such data).
  holdingRow:(m,side)=>{const no=side==='no',yes=(m.history||[]).map(x=>x[1]).concat(Number(m.prices[0])),k=p=>Math.round(p*1000),now=k(yes.at(-1)),d=yes.length>1?now-k(yes[0]):m.oneDayPriceChange==null?null:Math.round(m.oneDayPriceChange*1000),chg=d==null?null:no?-d:d,up=(chg??0)>=0,f=n=>(n/10).toFixed(1);return `<div class="position-row monitor-row"><div class="monitor-top"><p class="title">${U.esc(m.question)}</p><span class="${no?'no':'yes'}-label">${no?'NO':'YES'}</span></div><div class="holding-data"><div class="holding-prob"><b>${f(no?1000-now:now)}%</b>${chg==null?'':`<span class="${up?'positive':'negative'}">${up?'+':'−'}${f(Math.abs(chg))}%</span>`}</div>${U.spark(no?yes.map(p=>1-p):yes,up)}</div></div>`},
  // 候选市场: 买入 YES / 买入 NO show that side's market and model probability; 观望 shows YES.
  candidateRow:(m,d)=>{const no=d==='no',mid=Engine.risk(m)==='mid',mk=Engine.pct(Number(m.prices[0])),md=Engine.pct(Engine.model(m)),c=U.t('：',': ');return `<div class="position-row monitor-row"><div class="monitor-top"><p class="title">${U.esc(m.question)}</p><span class="${Engine.decisionClass(d)}">${({yes:U.t('买入 YES','Buy YES'),no:U.t('买入 NO','Buy NO'),watch:U.t('观望','Watch')})[d]}</span></div><div class="candidate-data"><span>${U.t('市场概率','Market')}${c}<b>${no?mk.no:mk.yes}%</b></span><span>${U.t('模型概率','Model')}${c}<b>${no?md.no:md.yes}%</b></span><span>${U.t('风险','Risk')}${c}<b>${mid?U.t('中','Medium'):U.t('低','Low')}</b></span></div></div>`},
  // Leo 11-05 #6 #7: official community channels are Envo and DeBox; group links still to come from Leo (empty url = icon only).
  social:[['Envo','assets/social-envo.png',''],['DeBox','assets/social-debox.png','']],
  socialIcons:(cls='social-icons')=>`<span class="${cls}">${U.social.map(([n,src,url])=>url?`<a href="${url}" target="_blank" rel="noopener noreferrer" aria-label="${n}"><img src="${src}" alt=""></a>`:`<span role="img" aria-label="${n}"><img src="${src}" alt=""></span>`).join('')}</span>`,
  // 最近成交: one real public Polymarket fill per event (side, outcome, time, USDC amount), newest first.
  // Sides follow Leo's mock (buy, sell, buy): each event's latest fill of that side, else its latest fill.
  latestTrades:()=>{const by={};for(const tr of D.trades)if(tr.notional>=10)(by[tr.marketId]??=[]).push(tr);return Object.values(by).map(g=>g.sort((a,b)=>b.timestamp-a.timestamp)).sort((a,b)=>b[0].timestamp-a[0].timestamp).slice(0,3).map((g,i)=>g.find(tr=>tr.side===(i===1?'SELL':'BUY'))||g[0]).sort((a,b)=>b.timestamp-a.timestamp)},
  // Agent 交易执行 row; Overview 交易动态 reuses it (Leo PRD 11-10 §4).
  tapeRow:tr=>{const t=U.t;return `<div class="tape-row"><div class="tape-transaction"><span class="tape-tx">${icon('cube','',11)}${tr.transactionHash.slice(0,6)}…${tr.transactionHash.slice(-4)}</span><p title="${U.esc(tr.question)}">${U.esc(tr.question)}</p><time>${U.stamp(tr.timestamp*1000,true)}</time></div><div><span class="${tr.side==='BUY'?'yes':'no'}-label">${tr.side==='BUY'?'↙':'↗'} ${tr.side==='BUY'?t('买入','BUY'):t('卖出','SELL')}</span><span class="tape-outcome">${U.esc(tr.outcome.toUpperCase())} · ${U.usd(tr.price)}</span></div><div class="tape-notional"><b class="${tr.side==='BUY'?'positive':'negative'}">${U.money(tr.notional)}</b><a href="https://polygonscan.com/tx/${U.esc(tr.transactionHash)}" target="_blank" rel="noopener noreferrer" aria-label="${t('查看链上交易','View onchain transaction')}">${icon('external','',13)}</a></div></div>`},
  tradeRow:tr=>`<div class="position-row monitor-row trade-mini"><div><p class="title">${U.esc(tr.question)}</p><p class="trade-meta">${tr.side==='SELL'?U.t('卖出','Sell'):U.t('买入','Buy')} ${U.esc(String(tr.outcome).toUpperCase())} · ${U.stamp(tr.timestamp*1000,true)}</p></div><b class="trade-amt">${U.money(tr.notional)} USDC</b></div>`,
  custodyInfo:()=>{if(!S.custody)return null;const total=U.custody.days*86400000,elapsed=Math.max(0,Date.now()-S.custody.startedAt),left=Math.max(0,total-elapsed),p=n=>String(n).padStart(2,'0');return {left,canStop:elapsed>=U.custody.minHours*3600000,progress:Math.min(100,elapsed/total*100),time:`${p(Math.floor(left/86400000))}D ${p(Math.floor(left%86400000/3600000))}H ${p(Math.floor(left%3600000/60000))}M`}},
  // Progress area per Leo PRD 11-10 §5.1 images: all phases count up; the bar of 平仓 uses this cycle's random 3–5H as its scale.
  agentState:()=>{
    const t=U.t,c=U.custodyInfo();
    const elapsed=Math.max(0,S.elapsed+Math.floor((Date.now()-S.startedAt)/1000));
    const two=x=>String(x).padStart(2,'0'),hms=n=>`${two(Math.floor(n/3600))}:${two(Math.floor(n%3600/60))}:${two(n%60)}`,ms=n=>`${two(Math.floor(n/60))}:${two(n%60)}`;
    const pct=(a,b)=>Math.min(100,a/b*100),run=t('运行周期 · 8小时','Run cycle · 8H'),e8=Math.min(elapsed,28800);
    if(S.agentState==='running'&&c)return {label:t('托管中','In custody'),tone:'',icon:'lock',primary:t('托管中','In custody'),primaryIcon:'lock',locked:true,period:t(`托管期限 · ${U.custody.days}天`,`Custody · ${U.custody.days}D`,{vi:`Ủy thác · ${U.custody.days} ngày`,ko:`위탁 · ${U.custody.days}일`}),big:hms(e8),caption:t('本周期已运行','This cycle'),progress:pct(e8,28800),left:'00:00:00',mid:pct(e8,28800).toFixed(1)+'%',right:'08:00:00',foot:t('托管剩余 ','Custody left ')+c.time,footIcon:'clock',bar:''};
    const exit=S.exitSec||14400,ex=Math.min(elapsed,exit),open=elapsed>=U.continueAfterSec;
    const states={
      inactive:{label:t('未激活','Inactive'),tone:'gray',icon:'play',primary:t('开始运行','Start running'),primaryIcon:'play',locked:false,period:run,big:'00:00:00',caption:t('已运行时间','Elapsed'),progress:0,left:'00:00:00',mid:'0.0%',right:'08:00:00',foot:t('输入资金后开始运行','Enter an amount to start'),footIcon:'info',bar:''},
      running:{label:t('运行中','Running'),tone:'',icon:'play',primary:t('运行中','Running'),primaryIcon:'pulse',locked:true,period:run,big:hms(e8),caption:t('已运行时间','Elapsed'),progress:pct(e8,28800),left:'00:00:00',mid:pct(e8,28800).toFixed(1)+'%',right:'08:00:00',foot:t('距离运行周期结束还有 ','Cycle ends in ')+hms(28800-e8),footIcon:'clock',bar:''},
      cancelling:{label:t('平仓中','Closing'),tone:'amber',icon:'down',primary:t('继续运行','Continue running'),primaryIcon:open?'play':'lock',locked:!open,period:t('预计耗时 · 3–5小时','Est. 3–5H'),big:hms(ex),caption:t('已用时间','Elapsed'),progress:pct(ex,exit),left:'00:00:00',mid:t('预计 3–5 小时','Est. 3–5H'),right:hms(exit),foot:t('正在处理未完成订单与持仓，实际完成时间取决于市场成交情况','Settling open orders and positions. The actual time depends on market fills'),footIcon:'info',bar:'amber'},
      resuming:{label:t('恢复中','Resuming'),tone:'blue',icon:'refresh',primary:t('继续运行','Continue running'),primaryIcon:'lock',locked:true,period:t('预计耗时 · 10分钟','Est. 10 min'),big:ms(Math.min(elapsed,U.resumeSec)),caption:t('已用时间','Elapsed'),progress:pct(elapsed,U.resumeSec),left:'00:00',mid:Math.round(pct(elapsed,U.resumeSec))+'%',right:t('预计 ','Est. ')+ms(U.resumeSec),foot:t('正在停止平仓流程并恢复交易系统','Stopping the exit and restoring trading'),footIcon:'refresh',bar:'blue'},
      stopped:{label:t('已停止','Stopped'),tone:'gray',icon:'stop',primary:t('继续运行','Continue running'),primaryIcon:'play',locked:false,period:run,big:'08:00:00',caption:t('本周期已结束','Cycle complete'),progress:100,left:'00:00:00',mid:'100%',right:'08:00:00',foot:t('盈亏已确定，可提出或继续运行','Results are final. Withdraw or continue'),footIcon:'check',bar:'done'}
    };
    if(S.product==='custody'){const go=t('继续托管','Continue custody'),term=t(`托管期限 · ${U.custody.days}天`,`Custody · ${U.custody.days}D`,{vi:`Ủy thác · ${U.custody.days} ngày`,ko:`위탁 · ${U.custody.days}일`});
      Object.assign(states.inactive,{primary:t('开始托管','Start custody'),period:term,foot:t('输入资金后开始托管','Enter an amount to start custody')});
      states.cancelling.primary=states.resuming.primary=go;Object.assign(states.stopped,{primary:go,foot:t('盈亏已确定，可提出或继续托管','Results are final. Withdraw or continue custody')})}
    return states[S.agentState]||states.running;
  }
};
