function footer(){if(S.route==='home')return Overview.footer();return `<footer class="footer"><span>© 2026 ${U.brand} · ${U.t('保留所有权利','All rights reserved')}</span><div class="footer-links"><a href="#whitepaper">${U.t('白皮书','Whitepaper')}</a><a href="#sources">${U.t('数据来源','Data sources')}</a><a href="#guide">${U.t('使用指南','Documentation')}</a></div></footer>`}
function render(options={}){
  if(!D)return;
  const y=document.getElementById('main')?.scrollTop||0;
  S.theme=ForeaTheme.apply(S.themeMode);
  document.documentElement.lang=I18N.tag(S.lang);
  document.body.classList.toggle('review-mode',params.has('embed'));
  const fn=Pages[S.route]||Pages.home;
  document.title=({home:'Overview',agent:'Agent Trading',liquidity:'Liquidity Marketplace',tokenomics:'Tokenomics',account:'Portfolio',swap:'Swap',whitepaper:'Whitepaper',guide:'Documentation',sources:'Data Sources',rules:'Rules'})[S.route]+' · '+U.brand;
  document.getElementById('app').innerHTML=header()+`<main id="main" class="main">${fn()}${footer()}</main><button class="to-top" data-action="top" aria-label="${U.t('返回顶部','Back to top')}">${icon('up','',18)}</button><button class="review-fab" data-action="review">${icon('settings','',11)}${U.t('设计验收','Design review')}</button>`;
  if(options.preserve)document.getElementById('main').scrollTop=y;
  if(options.focus){const el=document.getElementById(options.focus);el?.focus({preventScroll:true});if(el?.type==='search')el.setSelectionRange(el.value.length,el.value.length)}
  updateScroll();
}
function route(){
  // remember where the user came from so secondary pages can go back to it (走查 #2)
  {const h=location.hash.slice(1)||'home';if(S.currentHash!==h){const m=document.getElementById('main');if(S.currentHash&&m)(S.scrollMemo||(S.scrollMemo={}))[S.currentHash]=m.scrollTop;S.prevHash=S.currentHash||'';S.currentHash=h}}
  const [path,sub]=location.hash.replace('#','').split('/');
  S.route=['agent','liquidity','tokenomics','account','swap','whitepaper','sources','guide','rules'].includes(path)?path:'home';
  if(S.route==='agent')S.agentTab=sub==='execution'?2:sub==='analysis'?1:sub==='monitoring'?3:0;
  if(S.route==='liquidity')S.liquidityTab=sub==='services'?1:0;
  S.accountSub=S.route==='account'&&['profile','consumption','activity'].includes(sub)?sub:'';
  closeOverlay();render();const main=document.getElementById('main');main?.scrollTo(0,S.scrollMemo?.[S.currentHash]||0);
  if(S.route==='home'&&sub){const el=document.getElementById('ov-'+sub);if(el&&main)main.scrollTo(0,el.getBoundingClientRect().top-main.getBoundingClientRect().top+main.scrollTop-12)}
}
