  'confirm-service':()=>{if(S.overlay!=='service-apply')return;const n=Number(document.getElementById('service-amount')?.value);const err=document.getElementById('service-error');if(!Number.isFinite(n)||n<1000||n>5000){err.textContent=U.t('请输入 1,000–5,000 USDC','Enter 1,000–5,000 USDC');return}if(n>S.walletBalance){err.innerHTML=`${U.t('钱包余额不足','Insufficient wallet balance')} <button class="text-link" data-action="funding-short" data-value="${n-S.walletBalance}">${U.t('准备 USDC','Get USDC')}</button>`;return}S.services.unshift({id:String(1043+S.services.length),marketId:S.selectedMarket,status:'active',amount:n,startedAt:Date.now()});S.walletBalance-=n;U.record('service-apply',-n);closeOverlay();location.hash='liquidity/services';S.liquidityTab=1;render();toast(U.t('流动性服务已开始','Liquidity service started'))},
  'service-detail':v=>{const s=S.services.find(s=>s.id===v);if(!s)return;const {t}=U,info=U.serviceInfo(s),start=s.startedAt||Date.now(),end=start+12*3600000,settle=end+U.serviceSettleMs,done=k=>['active','ended','settled','withdrawn'].indexOf(info.status)>=k;const steps=[[t('已开始','Started'),start,true],[done(1)?t('已结束','Ended'):t('预计结束','Ends'),end,done(1)],[done(2)?t('已结算','Settled'):t('预计结算','Settles'),settle,done(2)],...(info.status==='withdrawn'?[[t('已提出','Withdrawn'),s.withdrawnAt||settle,true]]:[])];sheet(t('服务详情','Service details')+' #'+s.id,`<p>${U.esc(D.markets.find(m=>m.id===s.marketId)?.question||'')}</p><ol class="service-steps">${steps.map(([l,at,ok])=>`<li class="${ok?'done':''}"><span>${l}</span><time>${U.stamp(at)} UTC+8</time></li>`).join('')}</ol><div>${[[t('锁定资金','Locked funds'),U.money(s.amount)+' USDC'],[t('服务费（4%）','Service fee (4%)'),'−'+U.money(info.fee)+' USDC'],[info.status==='withdrawn'?t('已返回钱包','Returned to wallet'):t('到期返还','Amount returned'),U.money(info.claimable)+' USDC']].map(([a,b])=>`<div class="confirm-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div>${info.status==='settled'?`<div class="confirm-actions"><button class="btn secondary" data-action="close">${t('关闭','Close')}</button><button class="btn primary" data-action="service-withdraw" data-value="${s.id}">${icon('wallet','',14)}${t('提出','Withdraw')}</button></div>`:`<button class="btn secondary block" data-action="close">${t('关闭','Close')}</button>`}`)},
  'service-withdraw':v=>{const s=S.services.find(s=>s.id===v);if(!s)return;const info=U.serviceInfo(s);if(info.status!=='settled')return;S.withdrawService=s.id;sheet(U.t('提出资金','Withdraw funds'),`<div class="confirm-row" style="margin-top:18px"><span>${U.t('锁定资金','Locked funds')}</span><b>${U.money(s.amount)} USDC</b></div><div class="confirm-row" data-row="service-fee"><span>${U.t('服务费（4%）','Service fee (4%)')}</span><b>−${U.money(info.fee)} USDC</b></div><div class="confirm-row"><span>${U.t('返回金额','Amount')}</span><b data-row="service-cash">${U.money(info.claimable)} USDC</b></div><div class="confirm-row"><span>${U.t('到账账户','To account')}</span><b>${U.address()}</b></div><div class="confirm-actions"><button class="btn secondary" data-action="close">${U.t('取消','Cancel')}</button><button class="btn primary" data-action="confirm-service-withdraw" data-value="${s.id}">${U.t('确认提出','Confirm withdrawal')}</button></div>`,'sheet','service-withdraw')},
  'confirm-service-withdraw':v=>{if(S.overlay!=='service-withdraw'||S.withdrawService!==v)return;const s=S.services.find(s=>s.id===v);if(!s)return;const info=U.serviceInfo(s);if(info.status!=='settled')return;S.withdrawService=null;s.withdrawn=true;s.withdrawnAt=Date.now();S.walletBalance=Number((S.walletBalance+info.claimable).toFixed(8));U.record('service-withdraw',info.claimable);closeOverlay();render({preserve:true});toast(U.t('已返回钱包','Returned to your wallet'))},
  chapter:v=>document.getElementById(v)?.scrollIntoView({behavior:'smooth'}),
  maintenance:()=>sheet(U.t('引擎维护中','Engine maintenance'),`<p>${U.t('维护期间暂停发起新任务，资金与持仓可正常查看','New tasks are paused during maintenance. Balances and positions stay visible')}</p><div class="info-box">${U.badge(U.t('维护中','Maintenance'),'amber')}</div><button class="btn secondary block" data-action="close">${U.t('返回','Back')}</button>`)
