document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');
  if(el&&!el.disabled){e.preventDefault();(actions[el.dataset.action]||Wallet.actions[el.dataset.action]||Tokenomics.actions[el.dataset.action]||Account.actions[el.dataset.action]||Activity.actions[el.dataset.action]||Community.actions[el.dataset.action]||Overview.actions[el.dataset.action])?.(el.dataset.value);return}
  if(e.target.dataset.dismiss)closeOverlay();
  if(e.target.closest('#overlay a[href^="#"]')){const href=e.target.closest('a').getAttribute('href');closeOverlay();if(location.hash===href){route()}}
});
document.addEventListener('input',e=>{
  Tokenomics.onInput(e);Account.onInput(e);Activity.onInput(e);Wallet.onInput(e);
  if(e.target.id==='agent-amount'){S.amount=Number(e.target.value);const hint=document.getElementById('agent-amount-hint'),n=Number(e.target.value),bad=e.target.value!==''&&(!Number.isFinite(n)||n<20||n>1000);if(hint){hint.textContent=bad?U.t('请输入 20–1,000 USDC','Enter 20–1,000 USDC'):U.t('限额 20–1,000 USDC','Limit 20–1,000 USDC');hint.classList.toggle('invalid',bad)}}
  if(e.target.id==='service-amount'){const n=Number(e.target.value);document.getElementById('service-fee').textContent=U.money(n*.04);document.getElementById('service-return').textContent=U.money(n*.96);document.getElementById('service-error').textContent=!Number.isFinite(n)||n<1000||n>5000?U.t('请输入 1,000–5,000 USDC','Enter 1,000–5,000 USDC'):n>S.walletBalance?U.t('钱包余额不足','Insufficient wallet balance'):''}
  if(e.target.id==='market-search'){S.search=e.target.value;S.marketPage=0;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>render({preserve:true,focus:'market-search'}),150)}
});
document.addEventListener('change',e=>{Activity.onChange(e);if(e.target.id==='book-market'){S.bookMarket=e.target.value;render({preserve:true});document.querySelector('.book-detail')?.setAttribute('open','')}if(e.target.id==='tape-market'){S.tapeMarket=e.target.value;render({preserve:true})}});
document.addEventListener('scroll',updateScroll,true);
document.addEventListener('keydown',e=>{
  if(e.key==='Escape')closeOverlay();
  if(e.key==='Tab'&&document.querySelector('[role="dialog"]')){const dialog=document.querySelector('[role="dialog"]');const nodes=[...dialog.querySelectorAll('button,a,input,select,[tabindex]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===dialog)){e.preventDefault();first?.focus()}}
  if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){const el=document.getElementById('market-search');if(el){e.preventDefault();el.focus()}}
});
window.addEventListener('hashchange',route);
window.addEventListener('scroll',updateScroll,{passive:true});
var mobile=innerWidth<=760;
window.addEventListener('resize',()=>{const next=innerWidth<=760;if(next!==mobile){mobile=next;render({preserve:true})}});
setInterval(()=>{
  let serviceChanged=false;
  for(const s of S.services){const info=U.serviceInfo(s);if(s.shownStatus&&s.shownStatus!==info.status)serviceChanged=true;s.shownStatus=info.status;const clock=document.querySelector('[data-service-clock="'+s.id+'"]');const fill=document.querySelector('[data-service-fill="'+s.id+'"]');if(clock)clock.textContent=info.time;if(fill)fill.style.width=info.progress+'%'}
  if(serviceChanged&&!S.overlay)render({preserve:true});
  const current=U.agentState(),setId=(id,v)=>{const el=document.getElementById(id);if(el&&el.textContent!==v)el.textContent=v};
  if(document.getElementById('agent-clock')){setId('agent-clock',current.big);setId('agent-mid',current.mid);setId('agent-foot',current.foot);const fill=document.querySelector('.my-agent .progress>span');if(fill)fill.style.width=current.progress+'%';if(S.shownLock!==undefined&&S.shownLock!==current.locked&&!S.overlay)render({preserve:true})}
  S.shownLock=current.locked;
  if(document.getElementById('agent-pnl')){const p=U.performance(),sg=n=>(n>=0?'+':'−')+U.money(Math.abs(n));setId('agent-pnl',S.capital?sg(p.gross):'0.00');setId('agent-pnl-pct',S.capital?U.pct(p.grossPct):'0.00%');setId('agent-equity',U.money(p.equity));setId('agent-equity-pct',S.capital?U.pct(p.netPct):'0.00%');const el=document.getElementById('agent-pnl');if(el)el.parentElement.className='fund-number '+(S.capital?(p.gross>=0?'positive':'negative'):'')}
  const advance=()=>{let changed=false;const custody=S.agentState==='running'?U.custodyInfo():null;
  // Custody: 8H cycles renew automatically (1 MAAT each); ends at 30 days, or early when project MAAT runs out (demo choice).
  if(custody){if(custody.left===0){endCustody();changed=true}else if(S.elapsed+(Date.now()-S.startedAt)/1000>=28800){if(S.tokenProjectBalance<1){endCustody();toast(U.t('项目 MAAT 不足，托管已停止','Not enough project MAAT. Custody stopped'))}else{S.realized=Number(((S.realized||0)+U.cycleTarget()).toFixed(2));newCycle();consumeDemoToken();S.elapsed=0;S.startedAt=Date.now()}changed=true}else if(S.custody.shownCanStop!==custody.canStop){const was=S.custody.shownCanStop;S.custody.shownCanStop=custody.canStop;if(was!==undefined&&!S.overlay)changed=true}}
  else if(S.agentState==='running'&&S.elapsed+(Date.now()-S.startedAt)/1000>=28800){enterExit();changed=true}
  if(S.agentState==='resuming'&&S.elapsed+(Date.now()-S.startedAt)/1000>=U.resumeSec){S.agentState='running';S.elapsed=0;S.startedAt=Date.now();changed=true}
  if(S.agentState==='cancelling'&&S.elapsed+(Date.now()-S.startedAt)/1000>=(S.exitSec||14400)){S.agentState='stopped';S.elapsed=0;S.startedAt=Date.now();changed=true}
  return changed};
  const a=advance(),b=withOther(advance);if(a||b)render({preserve:true});
},1000);
function refreshAutoTheme(){if(S.themeMode==='auto'&&ForeaTheme.resolve('auto')!==S.theme){S.theme=ForeaTheme.apply('auto');render({preserve:true})}}
